svg.script:
// A deck physically contains its cards: each one is a single_poker_card
// toy inside the deck's tt_contents, in order: the last child is the top
// card. Stocking places 52 cards, each of which moves itself into the deck
// as it is initialized (see single_poker_card.initialize). Draw takes cards
// off the top onto the table; a card's own 'Return to deck' puts it back on
// top. Reshuffle reorders the cards in the deck and nothing else. Deleting
// a card is a separate thing: it is gone, not returned.
var poker_deck = {

  SUIT_COUNT: 4,
  RANK_COUNT: 13,
  MAX_DRAW:   5,

  menu: {
    'Draw': {
      eventName: 'poker_deck_draw',
      applicable: (node) => poker_deck._contents(node).length > 0,
      handler: function(evt, { num } = {}) {
        poker_deck._draw(this, num ?? 1)
      },
      uiLabel: (node) => `Draw (${poker_deck._contents(node).length})`,
      radial: (node) => ({
        'How many': { param: 'num', type: 'integer', default: 1, min: 1,
                      max: Math.max(1, Math.min(poker_deck.MAX_DRAW, poker_deck._contents(node).length)) },
      }),
    },
    'Reshuffle': {
      eventName: 'poker_deck_reshuffle',
      applicable: (node) => poker_deck._contents(node).length > 1,
      handler: function(evt) {
        poker_deck._reshuffle(this)
      },
      radial: true,
    },
  },

  // Runs when a deck is placed by a user. A detached preview, or a clone
  // that already carries its cards, is left alone.
  initialize: function(elem) {
    if (!elem.closest('#toys-layer')) return
    if (poker_deck._contents(elem).length > 0) return
    const deckId = elem.getAttribute('data-id')
    const color = elem.getAttribute('data-color') || undefined
    const { x, y, w, h } = poker_deck._own_box(elem)
    const all = []
    for (let suit = 1; suit <= poker_deck.SUIT_COUNT; suit++) {
      for (let rank = 1; rank <= poker_deck.RANK_COUNT; rank++) all.push({ suit, rank })
    }
    while (all.length) {
      const pick = all.splice(Math.floor(Math.random() * all.length), 1)[0]
      poker_deck._event('toy:add', {
        toyType: 'single_poker_card',
        x: x + w / 2,
        y: y + h / 2,
        color,
        initArgs: { color, suit: pick.suit, rank: pick.rank, deck: deckId },
      })
    }
  },

  _contents: function(elem) {
    const group = elem.querySelector('.tt_contents')
    return group ? [...group.querySelectorAll(':scope > .toy')] : []
  },

  _own_box: function(elem) {
    const svg = elem.querySelector(':scope > svg')
    return {
      x: parseFloat(svg?.getAttribute('x'))      || 0,
      y: parseFloat(svg?.getAttribute('y'))      || 0,
      w: parseFloat(svg?.getAttribute('width'))  || 0,
      h: parseFloat(svg?.getAttribute('height')) || 0,
    }
  },

  // Deals the top num cards, the top one first, fanned out to the right
  // of the deck.
  _draw: function(elem, num) {
    const cards = poker_deck._contents(elem)
    const { x, y, w, h } = poker_deck._own_box(elem)
    const count = Math.min(num, cards.length)
    for (let i = 0; i < count; i++) {
      const card = cards.pop()
      card.setAttribute('data-above', '')
      card.setAttribute('data-below', '')
      const cardSvg = card.querySelector(':scope > svg')
      const cw = parseFloat(cardSvg?.getAttribute('width'))  || 0
      const ch = parseFloat(cardSvg?.getAttribute('height')) || 0
      poker_deck._event('toy:reparent', { id: card.getAttribute('data-id'), containerId: null })
      // Overrides reparentToyDom's own "preserve visual position" default.
      cardSvg.setAttribute('x', String(x + w + 60 + 20 * i - cw / 2))
      cardSvg.setAttribute('y', String(y + h / 2 - ch / 2))
    }
  },

  // Fisher-Yates over the cards inside the deck, then re-append them in
  // the new order. Cards outside the deck are not touched.
  _reshuffle: function(elem) {
    const cards = poker_deck._contents(elem)
    for (let i = cards.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[cards[i], cards[j]] = [cards[j], cards[i]]
    }
    const group = elem.querySelector('.tt_contents')
    cards.forEach(card => group.appendChild(card))
  },

  _event: function(evName, args) {
    const detail = { ...args, retval: {} };
    document.dispatchEvent(new CustomEvent(evName, { detail }));
    if (detail.error) throw new Error(detail.error);
    return detail.retval;
  },

}
